using System;using System.Drawing;class GridTest{[STAThread]static void Main(){using(var c=new Chart())using(var b=new Bitmap(900,700)){c.Size=b.Size;var inv=new Inventory();var r=new Device("Router"){Role="master"};var d=new Device("Raster");inv.Devices.AddRange(new[]{r,d});c.SetData(inv);int x=(int)r.Pos.X+70,y=(int)r.Pos.Y;foreach(var selection in new[]{r,d,r}){c.SelectDevice(selection);c.DrawToBitmap(b,c.ClientRectangle);bool colored=b.GetPixel(x,y).ToArgb()!=Color.White.ToArgb();if(colored!=(selection==r)||b.GetPixel(x,(int)d.Pos.Y).ToArgb()!=Color.White.ToArgb())throw new Exception("Zonen");}Console.WriteLine("OK");}}}